class Solution:
    def climbStairs(self, n: int) -> int:
        p, q, r = 0, 0, 1
        for i in range(1, n + 1):
            p = q
            q = r
            r = p + q
        return r

class Solution:
    def climbStairs(self, n: int) -> int:
        def mul(a, b):
            c = [[0] * 2 for _ in range(2)]
            for i in range(2):
                for j in range(2):
                    c[i][j] = a[i][0] * b[0][j] + a[i][1] * b[1][j]
            return c

        def pow_(a, n):
            res = [[1, 0], [0, 1]]
            while n > 0:
                if n & 1 == 1:
                    res = mul(res, a)
                a = mul(a, a)
                n >>= 1
            return res

        return pow_([[1, 1], [1, 0]], n)[0][0]

class Solution:
    def climbStairs(self, n: int) -> int:
        sqrt5 = math.sqrt(5)
        pow1 = ((1 + sqrt5) / 2) ** (n + 1)
        pow2 = ((1 - sqrt5) / 2) ** (n + 1)
        return int(round((pow1 - pow2) / sqrt5))
